class NVLeaveAccrualAdditionalAdjustment extends RunBaseBatch implements BatchRetryable
{
    HcmWorkerRecId       workerRecId;
    date                 todayDate;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        workerRecId
    #endmacro

}

Method.Source:
public HcmWorkerRecId parmWorkerRecId(HcmWorkerRecId _workerRecId = workerRecId)
{
    workerRecId = _workerRecId;

    return workerRecId;
}

public Object dialog()
{
    DialogRunbase       dialog = super();

    return dialog;
}

public void run()
{
    #OCCRetryCount
    try
    {
        todayDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
        this.processAdjustment();
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}

private void processAdjustment()
{

    HcmWorker                   worker;
    LeaveEnrollment             enrollment;        

    while select worker
        where workerRecId == 0 || worker.RecId == workerRecId
        join enrollment
            where enrollment.Worker == worker.RecId
            && enrollment.StartDate <= todayDate 
            && (enrollment.EndDate == dateNull() || enrollment.EndDate >= todayDate)
    {
        ttsbegin;
        this.processAdjustmentWorker(worker, enrollment);
        ttscommit;
    }
}

private void processAdjustmentWorker(HcmWorker _worker, LeaveEnrollment _enrollment)
{
    LeavePlanTier    tier;
    while select tier
        where tier.Plan == _enrollment.Plan
    {
        NVLeaveAccrualAdditionalProcess process = NVLeaveAccrualAdditionalProcess::construct();

        process.initPlanTier(todayDate, tier.Type, _worker, _enrollment, tier);
        process.parmCreateAdjustment(true);
        process.process();
    }
}

public boolean unpack(container packedClass)
{
    Version version = RunBase::getVersion(packedClass);
    ;
    switch (version)
    {
        case #CurrentVersion:
            [version,#CurrentList] = packedClass;
            break;
        default:
            return false;
    }

    return true;
}

public boolean validate(Object _calledFrom = null)
{
    return true;
}

static NVLeaveAccrualAdditionalAdjustment construct()
{
    return new NVLeaveAccrualAdditionalAdjustment();
}

static ClassDescription description()
{
    return "Adjust accrue leave and absence plans";
}

static void main(Args args)
{
    NVLeaveAccrualAdditionalAdjustment adjustment = NVLeaveAccrualAdditionalAdjustment::construct();
    xSysLastValue::deleteLast(adjustment);

    if(args.record())
    {
        HcmWorker worker = args.record();
        adjustment.parmWorkerRecId(worker.RecId);
    }
    if (adjustment.prompt())
        adjustment.runOperation();
}

[Hookable(false)]
public final boolean isRetryable()
{
    return true;
}
